using RAWSelectionAssistant.Core.Services.RawToJpeg;using RAWSelectionAssistant.Core.Services.Projects;using RAWSelectionAssistant.Core.Models;using System.Reflection;
namespace RAWSelectionAssistant.Tests;
[TestClass][DoNotParallelize]public class ViewingProxyTests
{
 [TestMethod]public async Task ExactProxySamplesMatchHistoricalFullFloatProxyAllOrientations(){for(ushort orientation=1;orientation<=8;orientation++){var decoder=new Owned(orientation);var pipeline=new RawMatchTiff16ProductPipeline(decoder);using var full=await pipeline.DecodeMasterAsync("owned.cr3");using var expected=pipeline.PreviewMaster(full,17);using var actual=await pipeline.DecodeViewingProxyAsync("owned.cr3",17);Assert.AreEqual(expected.Width,actual.Width);Assert.AreEqual(expected.Height,actual.Height);Assert.AreEqual(orientation,actual.Orientation);CollectionAssert.AreEqual(expected.Rgb32.ToArray(),actual.Rgb32.ToArray());} }
 [TestMethod]public void BoundedIndependentTiffOrientationRejectsMalformedAmbiguousAndAbsent(){var method=typeof(LibRawDecoder).GetMethod("TryReadTiffIfd0Orientation",BindingFlags.NonPublic|BindingFlags.Static)!;var root=Path.Combine(Path.GetTempPath(),"view-meta-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);foreach(bool little in new[]{true,false})foreach(ushort orientation in Enumerable.Range(1,8).Select(i=>(ushort)i)){var path=Path.Combine(root,"tiff.bin");Write(path,little,orientation,1);object[] args=[path,(ushort)0];Assert.IsTrue((bool)method.Invoke(null,args)!);Assert.AreEqual(orientation,(ushort)args[1]);}foreach(var pair in new[]{(v:(ushort)0,n:1),(v:(ushort)9,n:1),(v:(ushort)1,n:2),(v:(ushort)1,n:0)}){var path=Path.Combine(root,"bad.bin");Write(path,true,pair.v,pair.n);Assert.IsFalse((bool)method.Invoke(null,[path,(ushort)0])!);} }
 static void Write(string path,bool little,ushort orientation,int count){using var f=File.Create(path);void U16(ushort v){Span<byte>b=stackalloc byte[2];if(little)System.Buffers.Binary.BinaryPrimitives.WriteUInt16LittleEndian(b,v);else System.Buffers.Binary.BinaryPrimitives.WriteUInt16BigEndian(b,v);f.Write(b);}void U32(uint v){Span<byte>b=stackalloc byte[4];if(little)System.Buffers.Binary.BinaryPrimitives.WriteUInt32LittleEndian(b,v);else System.Buffers.Binary.BinaryPrimitives.WriteUInt32BigEndian(b,v);f.Write(b);}f.Write(little?new byte[]{73,73}:new byte[]{77,77});U16(42);U32(8);U16((ushort)count);for(int i=0;i<count;i++){U16(274);U16(3);U32(1);U16(orientation);U16(0);}U32(0);}
 sealed class Owned(ushort orientation):IRawDecoder{public RawDecoderCapability GetCapability()=>throw new NotSupportedException();public Task<RawDecodedImage> DecodeAsync(string p,RawToJpegOptions o,CancellationToken t=default)=>Task.FromResult(RawDecodedImage.FromRgb48(53,31,318,Enumerable.Range(0,53*31*3).Select(i=>(ushort)(i*13%65535)).ToArray(),new("owned","owned",null,orientation,"sRGB")));}
}
